import React, { useState } from 'react';
import { uploadAndAnalyze } from '../services/api';
import { AnalysisResult, ModelMetrics, AttackStatistics } from '../types';

interface FileUploadProps {
    onAnalysisComplete?: (result: AnalysisResult, metrics: ModelMetrics, stats: AttackStatistics) => void;
}

interface AnalysisData {
    status: string;
    filename: string;
    total_records: number;
    attacks_detected: number;
    normal_records: number;
    attack_percentage: number;
    average_confidence: number;
}

const FileUpload: React.FC<FileUploadProps> = ({ onAnalysisComplete }) => {
    const [file, setFile] = useState<File | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [uploading, setUploading] = useState(false);
    const [analyzing, setAnalyzing] = useState(false);
    const [isUploaded, setIsUploaded] = useState(false);
    const [analysisResult, setAnalysisResult] = useState<AnalysisData | null>(null);

    const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = event.target.files?.[0];
        if (selectedFile && (selectedFile.type === 'text/csv' || selectedFile.name.endsWith('.parquet'))) {
            setFile(selectedFile);
            setError(null);
        } else {
            setError('Please upload a valid CSV or Parquet file.');
            setFile(null);
        }
    };

    const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        e.currentTarget.classList.add('drag-over');
    };

    const handleDragLeave = (e: React.DragEvent<HTMLDivElement>) => {
        e.currentTarget.classList.remove('drag-over');
    };

    const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        e.currentTarget.classList.remove('drag-over');
        const droppedFile = e.dataTransfer.files?.[0];
        if (droppedFile && (droppedFile.type === 'text/csv' || droppedFile.name.endsWith('.parquet'))) {
            setFile(droppedFile);
            setError(null);
        } else {
            setError('Please drop a valid CSV or Parquet file.');
        }
    };

    // 📤 STEP 1: Upload fichier
    const handleUpload = async () => {
        if (!file) return;
        setUploading(true);
        setError(null);

        try {
            // L'upload se fait juste pour vérifier le fichier
            // On ne lance pas l'analyse ici
            setIsUploaded(true);
        } catch (err) {
            setError('Upload failed');
            console.error(err);
        } finally {
            setUploading(false);
        }
    };

    // 🔮 STEP 2: Analyze - Lance les prédictions
    const handleAnalyze = async () => {
        if (!file) return;
        setAnalyzing(true);
        setError(null);

        try {
            const result = await uploadAndAnalyze(file);

            if (result.status !== 'success') {
                throw new Error(result.message || 'Analysis failed');
            }

            setAnalysisResult(result);

            // Préparer les données pour le callback
            const analysisData: AnalysisResult = {
                status: result.status,
                total_records: result.total_records,
                attacks_detected: result.attacks_detected,
                normal_records: result.normal_records,
                attack_percentage: result.attack_percentage,
                average_confidence: result.average_confidence
            };

            const metrics: ModelMetrics = {
                accuracy: result.average_confidence,
                precision: result.average_confidence,
                recall: result.average_confidence,
                f1_score: result.average_confidence
            };

            const stats: AttackStatistics = {
                total_attacks: result.attacks_detected,
                avg_confidence: result.average_confidence
            };

            if (onAnalysisComplete) {
                onAnalysisComplete(analysisData, metrics, stats);
            }
        } catch (err) {
            const errorMessage = err instanceof Error ? err.message : 'Analysis failed';
            setError(errorMessage);
            console.error(err);
        } finally {
            setAnalyzing(false);
        }
    };

    // 🔄 Reset et réupload
    const handleReset = () => {
        setFile(null);
        setIsUploaded(false);
        setAnalysisResult(null);
        setError(null);
    };

    return (
        <div>
            {/* 🔴 PHASE 1: Upload fichier */}
            {!isUploaded && !analysisResult && (
                <div>
                    <div 
                        className="file-upload-area"
                        onDragOver={handleDragOver}
                        onDragLeave={handleDragLeave}
                        onDrop={handleDrop}
                    >
                        <div className="upload-icon">▲</div>
                        <h2 className="upload-title">Upload Your Dataset</h2>
                        <p className="upload-subtitle">Drag and drop your file here or click to select</p>
                        <p className="file-extensions">Supported: .csv or .parquet</p>
                        <input
                            type="file"
                            accept=".csv,.parquet"
                            onChange={handleFileChange}
                            disabled={uploading}
                            id="file-input"
                            style={{ display: 'none' }}
                        />
                        <label htmlFor="file-input" style={{ cursor: 'pointer' }}>
                            <button 
                                type="button"
                                className="btn btn-primary"
                                disabled={uploading}
                                onClick={() => document.getElementById('file-input')?.click()}
                            >
                                Choose File
                            </button>
                        </label>
                        {file && (
                            <p className="upload-success">✓ {file.name}</p>
                        )}
                    </div>

                    {/* Upload Button */}
                    <div style={{ marginBottom: '24px', marginTop: '24px' }}>
                        <button
                            onClick={handleUpload}
                            className="btn btn-primary"
                            style={{ width: '100%' }}
                            disabled={!file || uploading}
                        >
                            {uploading ? 'Uploading...' : 'Upload'}
                        </button>
                    </div>
                </div>
            )}

            {/* 🟢 PHASE 2: Après upload - Visualize/Analyze buttons */}
            {isUploaded && !analysisResult && (
                <div className="card" style={{ marginBottom: '24px', backgroundColor: 'rgba(102, 126, 234, 0.05)' }}>
                    <div style={{ padding: '24px' }}>
                        <div style={{ display: 'flex', alignItems: 'center', marginBottom: '24px' }}>
                            <span style={{ fontSize: '24px', marginRight: '12px' }}>✓</span>
                            <div>
                                <h3 style={{ margin: 0, fontWeight: 'bold' }}>{file?.name}</h3>
                                <p style={{ margin: '4px 0 0 0', fontSize: '0.875rem', color: '#666' }}>
                                    File uploaded successfully
                                </p>
                            </div>
                        </div>

                        {/* Buttons */}
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
                            <button
                                onClick={() => alert('Visualize feature coming soon!')}
                                className="btn"
                                style={{
                                    backgroundColor: '#f0f0f0',
                                    color: '#333',
                                    border: '1px solid #ddd',
                                    padding: '12px 24px',
                                    borderRadius: '6px',
                                    fontSize: '1rem',
                                    fontWeight: '600',
                                    cursor: 'pointer',
                                    transition: 'all 0.3s ease'
                                }}
                            >
                                👁️ Visualize
                            </button>
                            <button
                                onClick={handleAnalyze}
                                className="btn btn-primary"
                                disabled={analyzing}
                                style={{
                                    padding: '12px 24px',
                                    borderRadius: '6px',
                                    fontSize: '1rem',
                                    fontWeight: '600',
                                    cursor: analyzing ? 'not-allowed' : 'pointer'
                                }}
                            >
                                {analyzing ? '🔄 Analyzing...' : '🔮 Analyze'}
                            </button>
                        </div>

                        {/* Reset button */}
                        <button
                            onClick={handleReset}
                            type="button"
                            style={{
                                marginTop: '12px',
                                width: '100%',
                                backgroundColor: 'transparent',
                                color: '#666',
                                border: '1px solid #ddd',
                                padding: '8px 16px',
                                borderRadius: '4px',
                                fontSize: '0.875rem',
                                cursor: 'pointer'
                            }}
                        >
                            Upload different file
                        </button>
                    </div>
                </div>
            )}

            {/* 🟡 PHASE 3: Résultats d'analyse */}
            {analysisResult && (
                <div>
                    <div className="card" style={{ marginBottom: '24px', backgroundColor: '#f0f8f4' }}>
                        <div style={{ padding: '24px' }}>
                            <h3 style={{ margin: 0, fontWeight: 'bold', marginBottom: '16px' }}>
                                ✓ Analysis Complete
                            </h3>

                            {/* Statistics Grid */}
                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px', marginBottom: '24px' }}>
                                {/* Total Records */}
                                <div style={{ backgroundColor: 'white', padding: '16px', borderRadius: '6px', border: '1px solid #e0e0e0' }}>
                                    <p style={{ margin: '0 0 8px 0', fontSize: '0.875rem', color: '#666' }}>
                                        Total Records
                                    </p>
                                    <p style={{ margin: 0, fontSize: '24px', fontWeight: 'bold', color: '#333' }}>
                                        {analysisResult.total_records}
                                    </p>
                                </div>

                                {/* Attacks Detected */}
                                <div style={{ backgroundColor: 'white', padding: '16px', borderRadius: '6px', border: '1px solid #e0e0e0' }}>
                                    <p style={{ margin: '0 0 8px 0', fontSize: '0.875rem', color: '#666' }}>
                                        Attacks Detected
                                    </p>
                                    <p style={{ margin: 0, fontSize: '24px', fontWeight: 'bold', color: '#d32f2f' }}>
                                        {analysisResult.attacks_detected}
                                    </p>
                                </div>

                                {/* Normal Records */}
                                <div style={{ backgroundColor: 'white', padding: '16px', borderRadius: '6px', border: '1px solid #e0e0e0' }}>
                                    <p style={{ margin: '0 0 8px 0', fontSize: '0.875rem', color: '#666' }}>
                                        Normal Records
                                    </p>
                                    <p style={{ margin: 0, fontSize: '24px', fontWeight: 'bold', color: '#388e3c' }}>
                                        {analysisResult.normal_records}
                                    </p>
                                </div>

                                {/* Attack Percentage */}
                                <div style={{ backgroundColor: 'white', padding: '16px', borderRadius: '6px', border: '1px solid #e0e0e0' }}>
                                    <p style={{ margin: '0 0 8px 0', fontSize: '0.875rem', color: '#666' }}>
                                        Attack Rate
                                    </p>
                                    <p style={{ margin: 0, fontSize: '24px', fontWeight: 'bold', color: '#f57c00' }}>
                                        {analysisResult.attack_percentage}%
                                    </p>
                                </div>
                            </div>

                            {/* Model Confidence */}
                            <div style={{ backgroundColor: 'white', padding: '16px', borderRadius: '6px', border: '1px solid #e0e0e0' }}>
                                <p style={{ margin: '0 0 8px 0', fontSize: '0.875rem', color: '#666' }}>
                                    Average Model Confidence
                                </p>
                                <p style={{ margin: 0, fontSize: '18px', fontWeight: 'bold', color: '#1976d2' }}>
                                    {(analysisResult.average_confidence * 100).toFixed(2)}%
                                </p>
                                <div style={{
                                    marginTop: '8px',
                                    height: '8px',
                                    backgroundColor: '#e0e0e0',
                                    borderRadius: '4px',
                                    overflow: 'hidden'
                                }}>
                                    <div style={{
                                        height: '100%',
                                        backgroundColor: '#1976d2',
                                        width: `${analysisResult.average_confidence * 100}%`,
                                        borderRadius: '4px'
                                    }}></div>
                                </div>
                            </div>

                            {/* Reset button */}
                            <button
                                onClick={handleReset}
                                style={{
                                    marginTop: '24px',
                                    width: '100%',
                                    backgroundColor: '#1976d2',
                                    color: 'white',
                                    border: 'none',
                                    padding: '12px 24px',
                                    borderRadius: '6px',
                                    fontSize: '1rem',
                                    fontWeight: '600',
                                    cursor: 'pointer'
                                }}
                            >
                                Upload new file
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Error Alert */}
            {error && (
                <div className="alert alert-error" style={{ marginBottom: '24px' }}>
                    <span>{error}</span>
                    <button 
                        className="alert-close"
                        onClick={() => setError(null)}
                        type="button"
                    >
                        ✕
                    </button>
                </div>
            )}
        </div>
    );
};

export default FileUpload;
